import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const d="/study/images/graphics/d3d12-texture-upload.svg",h=JSON.parse('{"title":"D3D12でテクスチャをアップロードする","description":"","frontmatter":{"title":"D3D12でテクスチャをアップロードする","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"CPU上の画像を行単位でUPLOADバッファに詰め、D3D12のテクスチャへコピーする。行の間隔、サブリソースの位置、状態遷移、フェンスで追うバッファの寿命を扱う。","aliases":["テクスチャアップロード","texture upload","RowPitch","GetCopyableFootprints","CopyTextureRegion","UPLOADヒープ","DEFAULTヒープ","COPY_DEST","PIXEL_SHADER_RESOURCE","staging buffer"],"verification":"MicrosoftのD3D12 API仕様とWindowsの開発資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/texture/d3d12-texture-upload.md","filePath":"graphics/texture/d3d12-texture-upload.md"}'),i={name:"graphics/texture/d3d12-texture-upload.md"};function s(c,e,n,p,l,f){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="d3d12でテクスチャをアップロードする" tabindex="-1">D3D12でテクスチャをアップロードする <a class="header-anchor" href="#d3d12でテクスチャをアップロードする" aria-label="Permalink to &quot;D3D12でテクスチャをアップロードする&quot;">​</a></h1><p>ゲームがDDSから読み出したバイトをピクセルシェーダーで使うまでには、CPUが書き込めるバッファを用意し、そこからD3D12のテクスチャへコピーする手順があります。CPU側ではファイルが決めた行の並びを読み、アップロード先にはD3D12が要求する間隔で各行を置きます。ここでは、2Dテクスチャを一つのDIRECTキューで扱う例を追います。<a href="/study/graphics/texture/dds-and-subresources.html">DDSとサブリソース</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/upload-and-readback-of-texture-data" target="_blank" rel="noreferrer">Microsoftのテクスチャ転送手順</a></p><figure class="study-figure"><img src="'+d+'" alt="4×4のRGBA8をコピーする例。CPU側は16バイト間隔で4行を持つ。UPLOADバッファでは行の間隔を256バイトに広げ、各行の先頭に16バイトずつ書く。CopyTextureRegionでDEFAULTテクスチャへコピーし、ピクセルシェーダーで読める状態へ遷移させる。" width="760" height="516" loading="lazy"><figcaption>同じ16バイトの行データを、コピー用バッファでは256バイト間隔で配置します。図の行と余白の幅は読みやすさのため調整しています。<a href="/study/images/graphics/d3d12-texture-upload.svg" target="_blank" rel="noopener noreferrer">コピー経路の図を拡大</a></figcaption></figure><h2 id="行に入るバイト数と、次の行までの間隔" tabindex="-1">行に入るバイト数と、次の行までの間隔 <a class="header-anchor" href="#行に入るバイト数と、次の行までの間隔" aria-label="Permalink to &quot;行に入るバイト数と、次の行までの間隔&quot;">​</a></h2><p><code>DXGI_FORMAT_R8G8B8A8_UNORM</code>の4×4 mipでは、1画素に4バイトを使うので1行のデータは16バイトです。この実践で作るDDSには4行を詰めて格納します。次の2×2 mipの1行は8バイトです。一般の画像入力では行の間に余白がある場合もあり、読み出し元の行の間隔は入力形式やデコーダーの情報から決めます。<a href="/study/graphics/texture/dds-and-subresources.html">DDSとサブリソース</a></p><p><code>GetCopyableFootprints</code>にテクスチャの記述と対象サブリソースの範囲を渡すと、バッファに置くための情報が返ります。mipごとに、どこに何バイト置くかを次の値で決めます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12device-getcopyablefootprints" target="_blank" rel="noreferrer">MicrosoftのGetCopyableFootprints</a></p><table tabindex="0"><thead><tr><th>戻る値</th><th>コピーでの使い方</th></tr></thead><tbody><tr><td><code>pLayouts[i].Offset</code></td><td>バッファ先頭からサブリソースの先頭までの位置。</td></tr><tr><td><code>pLayouts[i].Footprint.RowPitch</code></td><td>バッファに置いた行の先頭から次の行の先頭までのバイト数。</td></tr><tr><td><code>pRowSizeInBytes[i]</code></td><td>各行でコピーするデータのバイト数。行間の余白を含まない。</td></tr><tr><td><code>pNumRows[i]</code></td><td>コピーする行数。BC圧縮では画素の行ではなくブロックの行を数える。</td></tr><tr><td><code>pTotalBytes</code></td><td><code>BaseOffset = 0</code>で照会した場合に、要求した全サブリソースを収めるバッファの必要量。</td></tr></tbody></table><p>各行について、書き込み先を <code>Offset + 行番号 × RowPitch</code>、読み取り元を <code>元データ先頭 + 行番号 × 元の行間隔</code> で求めます。そこへ <code>pRowSizeInBytes[i]</code> バイトをコピーします。4×4 mipの例では、元の行を16バイトずつ進め、コピー用の行は256バイトずつ進めます。2×2 mipは自分の <code>Offset</code> から始めます。標準のコピー配置は行の間隔を256バイト、サブリソース先頭を512バイトの境界にそろえます。対応機能によって制約を緩和できる環境もありますが、この例ではAPIから得た標準の配置をそのまま使います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/upload-and-readback-of-texture-data#buffer-alignment" target="_blank" rel="noreferrer">Microsoftのバッファアラインメント</a></p><h2 id="アップロード用バッファからテクスチャへコピーする" tabindex="-1">アップロード用バッファからテクスチャへコピーする <a class="header-anchor" href="#アップロード用バッファからテクスチャへコピーする" aria-label="Permalink to &quot;アップロード用バッファからテクスチャへコピーする&quot;">​</a></h2><ol><li><code>D3D12_HEAP_TYPE_UPLOAD</code>のバッファを作り、<code>Map</code>で得たCPUアドレスに行データを書きます。バッファの状態は <code>GENERIC_READ</code> で、その中にコピー元として使える <code>COPY_SOURCE</code> が含まれます。</li><li><code>D3D12_HEAP_TYPE_DEFAULT</code>のテクスチャを <code>COPY_DEST</code> で作ります。バッファはコピー時の線形配置を持ち、テクスチャの内部配置はD3D12とデバイスが扱います。</li><li><code>CopyTextureRegion</code>をサブリソースごとに記録します。コピー元はバッファと <code>D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT</code>、コピー先はテクスチャと <code>D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX</code> で表します。例えばmip 0とmip 1を一つずつ指定します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-copytextureregion" target="_blank" rel="noreferrer">MicrosoftのCopyTextureRegion</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12#initial-states-for-resources" target="_blank" rel="noreferrer">Microsoftのリソース初期状態</a></li></ol><p>ピクセルシェーダーで読む場合は、コピーのあとにテクスチャを <code>COPY_DEST</code> から <code>PIXEL_SHADER_RESOURCE</code> へ変える遷移バリアを記録します。頂点シェーダーやコンピュートシェーダーから読む場合は、用途に応じて <code>NON_PIXEL_SHADER_RESOURCE</code> も使います。複数mipを順次アップロードする場合はサブリソース単位で状態を追い、描画が参照する範囲とSRV（シェーダーリソースビュー）が見せる範囲を合わせます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12" target="_blank" rel="noreferrer">Microsoftのリソース状態と遷移バリア</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_tex2d_srv" target="_blank" rel="noreferrer">Microsoftの2DテクスチャSRV</a></p><h2 id="キューの完了と、メモリを再利用できる時点" tabindex="-1">キューの完了と、メモリを再利用できる時点 <a class="header-anchor" href="#キューの完了と、メモリを再利用できる時点" aria-label="Permalink to &quot;キューの完了と、メモリを再利用できる時点&quot;">​</a></h2><p>コマンドリストを提出してから、同じキューに <code>ID3D12CommandQueue::Signal</code> でフェンス値を積みます。CPUがその値の到達を確認すると、そのシグナルより前に積んだ処理が終わったことが分かります。CPU側の画像はUPLOADバッファへの書き込み後に手放せます。UPLOADバッファの該当範囲は、GPUが読み終えるまで上書きせず、バッファも保持します。描画などから使うDEFAULTテクスチャやSRVは、その後の利用の完了まで保持します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによるリソース管理</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命</a></p><p>同じDIRECTキューでは、コピー、遷移、描画を順に積めます。コピーを専用のCOPYキューに分ける場合は、消費側のキューにフェンスの待機を積み、COPYとDIRECT間の <code>COMMON</code> の規則も踏まえて状態を管理します。フェンスはキュー間の順序を作り、リソースの状態は次にどのアクセスを行うかを表します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">Microsoftの複数エンジン間の同期</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ne-d3d12-d3d12_resource_states" target="_blank" rel="noreferrer">MicrosoftのCOMMON状態の規則</a> · <a href="/study/graphics/api/directx12.html">DirectX 12の基礎</a></p><p>実践では、WARPで2つのmipをアップロードし、テクスチャを <code>COPY_SOURCE</code> にしてREADBACKバッファへコピーします。フェンスの到達後にCPUでバッファを読み、行データが元のDDSと一致することを確かめます。アセットをそのまま描画に使う工程では、利用するシェーダーに合う状態とビューを用意します。<a href="/study/practice/graphics/dds-upload-observation.html">DDSを転送して読み戻すC++実践</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/readback-data-using-heaps" target="_blank" rel="noreferrer">MicrosoftのREADBACK手順</a> · <a href="/study/game/directstorage.html">DirectStorageからD3D12リソースへ届ける場合</a></p>',15)])])}const D=t(i,[["render",s]]);export{h as __pageData,D as default};
